<div class="top noprint"><div><a class="btn alt sm" href="/staff/invoices">← Invoices</a> <?= $i['request_id'] ? '<a class="btn alt sm" href="/staff/requests/' . (int) $i['request_id'] . '">Order ' . e($i['ref']) . '</a>' : '' ?></div><div><a class="btn alt" href="/staff/invoices/<?= (int) $i['id'] ?>.pdf">Download PDF</a> <button class="btn" data-print>Print</button></div></div>
<div class="inv">
<div class="hd"><div><h2 style="margin:0"><?= $i['kind'] === 'proforma' ? 'Pro-forma Invoice' : ($s['gstin'] ? 'Tax Invoice' : 'Invoice') ?></h2><b><?= e($i['number']) ?></b><br>Date: <?= e(fmt_date($i['issue_date'])) ?><br>Due: <?= e(fmt_date($i['due_date'])) ?><?php if ($i['status'] === 'paid'): ?><br>Paid in full: <?= e(fmt_date($i['paid_at'])) ?><?php endif; ?></div>
<div style="text-align:right"><b><?= e($s['name'] ?? '') ?></b><br><?= nl2br(e($s['address'] ?? '')) ?><br><?= e(trim(($s['phone'] ?? '') . ' ' . ($s['email'] ?? ''))) ?><?php if (!empty($s['gstin'])): ?><br>GSTIN: <?= e($s['gstin']) ?><?php endif; ?><?php if (!empty($s['pan'])): ?><br>PAN: <?= e($s['pan']) ?><?php endif; ?></div></div>
<?php if ($i['status'] !== 'issued'): ?><div style="margin:8px 0 16px"><span class="stamp <?= e($i['status']) ?>"><?= e(strtoupper(INVOICE_STATUSES[$i['status']])) ?></span></div><?php endif; ?>
<p><b>Bill to</b><br><?= e($i['bill_name']) ?><br><?= nl2br(e((string) $i['bill_address'])) ?><?= $i['bill_gstin'] ? '<br>GSTIN: ' . e($i['bill_gstin']) : '' ?><?= $i['bill_state'] ? '<br>State: ' . e($i['bill_state']) : '' ?></p>
<div class="tw"><table><tr><th>#</th><th>Description</th><th>HSN/SAC</th><th class="right">Qty</th><th class="right">Rate</th><th class="right">Amount</th></tr>
<?php foreach ($lines as $n => $l): ?><tr><td><?= $n + 1 ?></td><td><?= e($l['description']) ?></td><td><?= e((string) $l['hsn']) ?></td><td class="right"><?= e(rtrim(rtrim(number_format((float) $l['qty'], 2, '.', ''), '0'), '.')) ?></td><td class="right"><?= e(money($l['rate'])) ?></td><td class="right"><?= e(money($l['amount'])) ?></td></tr><?php endforeach; ?></table></div>
<?php if ($i['tax_inclusive']): ?><p class="muted" style="font-size:.85rem">Line rates include GST.</p><?php endif; ?>
<table class="tot"><tr><td>Taxable value</td><td class="right"><?= e(money($i['subtotal'])) ?></td></tr>
<?php $h = rtrim(rtrim(number_format((float) $i['gst_rate'] / ($i['tax_kind'] === 'igst' ? 1 : 2), 2, '.', ''), '0'), '.'); ?>
<?php if ($i['tax_kind'] === 'igst'): ?><tr><td>IGST @ <?= e($h) ?>%</td><td class="right"><?= e(money($i['igst'])) ?></td></tr>
<?php else: ?><tr><td>CGST @ <?= e($h) ?>%</td><td class="right"><?= e(money($i['cgst'])) ?></td></tr><tr><td>SGST @ <?= e($h) ?>%</td><td class="right"><?= e(money($i['sgst'])) ?></td></tr><?php endif; ?>
<tr><td>Total</td><td class="right"><?= e(money($i['total'])) ?></td></tr>
<?php if ($i['kind'] === 'tax' && (count($pays) || count($credits))): ?><tr><td style="font-weight:400">Paid / credited</td><td class="right" style="font-weight:400"><?= e(money(array_sum(array_column($pays, 'amount')) + array_sum(array_column($credits, 'total')))) ?></td></tr><tr><td>Balance due</td><td class="right"><?= e(money($balance)) ?></td></tr><?php endif; ?></table>
<?php if ($i['notes']): ?><p class="mt"><b>Notes</b><br><?= nl2br(e($i['notes'])) ?></p><?php endif; ?>
<?php if (!empty($s['bank'])): ?><p class="mt"><b>Bank details</b><br><?= nl2br(e($s['bank'])) ?></p><?php endif; ?>
<?php if (!empty($s['footer'])): ?><p class="mt muted"><?= nl2br(e($s['footer'])) ?></p><?php endif; ?>
</div>
<?php if ($i['kind'] === 'tax' && $i['status'] === 'issued'): ?><div class="card mt noprint"><h3>Record a payment</h3>
<form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="pay"><div class="row"><div><label>Amount (balance <?= e(money($balance)) ?>)</label><input name="amount" inputmode="decimal" value="<?= e(number_format($balance, 2, '.', '')) ?>"></div><div><label>Date</label><input type="date" name="paid_at" value="<?= e(date('Y-m-d')) ?>" required></div><div><label>Method</label><select name="method"><?= options(PAY_METHODS) ?></select></div><div><label>Reference (UTR / cheque no.)</label><input name="ref" maxlength="60"></div></div><button class="btn">Record payment</button></form></div><?php endif; ?>
<?php if (count($pays) || count($credits)): ?><div class="card mt noprint"><h3>Payments and credits</h3>
<?php foreach ($pays as $p): ?><div class="comment"><?= e(money($p['amount'])) ?> paid <?= e(fmt_date($p['paid_on'])) ?> &middot; <?= e($p['method']) ?><?= $p['ref'] ? ' &middot; ' . e($p['ref']) : '' ?> <span class="who">(<?= e((string) $p['uname']) ?>)</span></div><?php endforeach; ?>
<?php foreach ($credits as $c): ?><div class="comment"><a href="/staff/credit-notes/<?= (int) $c['id'] ?>"><?= e($c['number']) ?></a> credit <?= e(money($c['total'])) ?> &middot; <?= e(fmt_date($c['issue_date'])) ?> &middot; <?= e($c['reason']) ?></div><?php endforeach; ?></div><?php endif; ?>
<div class="card mt noprint"><h3>Actions</h3><div style="display:flex;gap:8px;flex-wrap:wrap">
<?php if ($i['status'] !== 'void' && $i['bill_email']): ?><form method="post" class="inline"><?= csrf_field() ?><input type="hidden" name="action" value="email"><button class="btn alt sm" data-confirm="E-mail this document to <?= e($i['bill_email']) ?>?">E-mail to customer</button></form><?php endif; ?>
<?php if ($i['kind'] === 'tax' && $i['status'] === 'issued' && $i['bill_email']): ?><form method="post" class="inline"><?= csrf_field() ?><input type="hidden" name="action" value="remind"><button class="btn alt sm" data-confirm="Send a payment reminder to <?= e($i['bill_email']) ?>?">Send payment reminder</button></form><?php endif; ?>
<?php if ($i['kind'] === 'proforma' && $i['status'] === 'issued'): ?><form method="post" class="inline"><?= csrf_field() ?><input type="hidden" name="action" value="convert"><button class="btn sm" data-confirm="Create the tax invoice from this pro-forma? The pro-forma is then closed.">Convert to tax invoice</button></form><?php endif; ?>
<?php if ($i['kind'] === 'tax' && $i['status'] !== 'void'): ?><a class="btn alt sm" href="/staff/credit-notes/new?invoice=<?= (int) $i['id'] ?>">Create credit note</a><?php endif; ?>
<?php if ($i['status'] === 'issued' && !count($pays) || (($i['status'] === 'paid' || count($pays)) && $i['status'] !== 'void' && can('team.manage'))): ?><form method="post" class="inline"><?= csrf_field() ?><input type="hidden" name="action" value="void"><button class="btn danger sm" data-confirm="Void this document? The number stays used.">Void</button></form><?php endif; ?></div>
<?php if (!$i['bill_email']): ?><p class="muted mt">Add the customer's e-mail address to e-mail documents (it is taken from the customer record when the invoice is created).</p><?php endif; ?></div>
